/* @autogenerated */
package net.civeira.phylax.feature.oauth.magiclink.application.usecase.requestmagiclink;

import java.net.URI;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Optional;
import java.util.UUID;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.security.SecureTokenService;
import net.civeira.phylax.feature.identity.tenant.domain.TenantRef;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.tenantconfig.domain.gateway.TenantConfigFilter;
import net.civeira.phylax.feature.identity.tenantconfig.domain.gateway.TenantConfigQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserFilter;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserQueryRepositoryGateway;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.feature.oauth.magiclink.domain.MagicLink;
import net.civeira.phylax.feature.oauth.magiclink.domain.gateway.MagicLinkEnabledGateway;
import net.civeira.phylax.feature.oauth.magiclink.domain.gateway.MagicLinkGateway;
import net.civeira.phylax.feature.oauth.magiclink.domain.gateway.MagicLinkMailGateway;

/**
 * Generates and delivers a magic link for passwordless login.
 *
 * <p>
 * All failures are silent: if the user is not found, the tenant is disabled, or the client is
 * invalid, the method returns without error to avoid user-enumeration.
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class RequestMagicLinkUsecase {

  private static final int DEFAULT_EXPIRES_MINUTES = 15;

  private final UserQueryRepositoryGateway users;
  private final TenantQueryRepositoryGateway tenants;
  private final TenantConfigQueryRepositoryGateway tenantConfigs;
  private final ClientStoreGateway clients;
  private final MagicLinkGateway gateway;
  private final MagicLinkMailGateway mailer;
  private final MagicLinkEnabledGateway enabled;
  private final SecureTokenService secureTokenService;

  /**
   * Public host for links and origins; without it, derived from the request.
   */
  @ConfigProperty(name = "oidc.base-url")
  private final Optional<String> baseUrl;

  public boolean isEnabled(String tenantName) {
    return enabled.isEnabled(tenantName);
  }

  public void request(String email, String clientId, String redirectUri, String tenantName,
      String scope, String state, String nonce) {
    if (!enabled.isEnabled(tenantName)) {
      return;
    }

    var tenant = tenants.find(TenantFilter.builder().name(tenantName).build());
    if (tenant.isEmpty() || !tenant.get().isEnabled()) {
      return;
    }

    var user = users.find(UserFilter.builder().nameOrEmail(email).tenant(tenant.get()).build());
    if (user.isEmpty() || !user.get().isEnabled()) {
      return;
    }

    if (clients.loadForAuthorization(tenantName, clientId, redirectUri).isEmpty()) {
      return;
    }

    String tenantUid = tenant.get().getUid();
    String userUid = user.get().getUid();

    String rawToken = secureTokenService.generate();
    String tokenHash = secureTokenService.hash(rawToken);
    int expiryMinutes =
        tenantConfigs.find(TenantConfigFilter.builder().tenant(tenant.get()).build())
            .map(c -> c.getMagicLinkExpiryMinutes()).orElse(DEFAULT_EXPIRES_MINUTES);
    OffsetDateTime expiresAt = OffsetDateTime.now(ZoneOffset.UTC).plusMinutes(expiryMinutes);

    MagicLink magicLink = MagicLink.builder().uid(UUID.randomUUID().toString()).tenantId(tenantName)
        .userUid(userUid).clientId(clientId).tokenHash(tokenHash).redirectUri(redirectUri)
        .scope(scope).state(state).nonce(nonce != null ? nonce : "")
        .createdAt(OffsetDateTime.now(ZoneOffset.UTC)).expiresAt(expiresAt).build();

    gateway.store(magicLink);

    String effectiveBaseUrl = resolveBaseUrl(redirectUri);
    String verifyUrl = effectiveBaseUrl.replaceAll("/+$", "") + "/oauth/openid/"
        + java.net.URLEncoder.encode(tenantName, java.nio.charset.StandardCharsets.UTF_8)
        + "/magic-link/verify?token="
        + java.net.URLEncoder.encode(rawToken, java.nio.charset.StandardCharsets.UTF_8)
        + "&client_id="
        + java.net.URLEncoder.encode(clientId, java.nio.charset.StandardCharsets.UTF_8);

    mailer.sendMagicLink(email, user.get().getName(), new TenantRef() {
      @Override
      public String getUid() {
        return tenantUid;
      }
    }, verifyUrl, expiresAt);
  }

  private String resolveBaseUrl(String redirectUri) {
    if (baseUrl.filter(url -> !url.isBlank()).isPresent()) {
      return baseUrl.get();
    }
    try {
      URI uri = URI.create(redirectUri);
      if (uri.getScheme() != null && uri.getAuthority() != null) {
        return uri.getScheme() + "://" + uri.getAuthority();
      }
    } catch (RuntimeException ignored) {
      log.debug("Unable to derive oidc.base-url from redirect_uri");
    }
    return "http://localhost";
  }
}
